import java.io.*; import java.util.*; class Result { public static String isValid(String s) { if (s == null || s.isEmpty()) return "NO"; Map<Character, Integer> charCounts = new HashMap<Character, Integer>(); for (char c : s.toCharArray()) { charCounts.put(c, charCounts.getOrDefault(c, 0) + 1); } Map<Integer, Integer> freqCounts = new HashMap<Integer, Integer>(); for (int count : charCounts.values()) { freqCounts.put(count, freqCounts.getOrDefault(count, 0) + 1); } if (freqCounts.size() == 1) return "YES"; if (freqCounts.size() > 2) return "NO"; List<Integer> keys = new ArrayList<Integer>(freqCounts.keySet()); int f1 = keys.get(0); int f2 = keys.get(1); int c1 = freqCounts.get(f1); int c2 = freqCounts.get(f2); if ((f1 == 1 && c1 == 1) || (f2 == 1 && c2 == 1)) return "YES"; if ((Math.abs(f1 - f2) == 1) && (c1 == 1 || c2 == 1)) return "YES"; return "NO"; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); String output = System.getenv("OUTPUT_PATH"); BufferedWriter bufferedWriter = new BufferedWriter(output != null ? new FileWriter(output) : new OutputStreamWriter(System.out)); String s = bufferedReader.readLine(); String result = Result.isValid(s); bufferedWriter.write(result); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }